const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
function typesWithImports(entry) {
  const exp = pkg.exports[entry];
  if (!exp) return null;
  const file = path.join(root, exp.types);
  let text = fs.readFileSync(file, "utf8");
  for (const m of text.matchAll(/from "(\.\.?\/[^"]+)\.js"/g)) {
    const dep = path.join(path.dirname(file), m[1] + ".d.ts");
    if (fs.existsSync(dep)) text += "\n" + fs.readFileSync(dep, "utf8");
  }
  return text;
}
const server = typesWithImports("./mcp/server");
if (!server) {
  console.error("FAIL: agents " + pkg.version + " has no agents/mcp/server entry point; createMcpHandler only takes an SDK v1 server");
  process.exit(1);
}
const mcp = typesWithImports("./mcp");
const checks = {
  serverExport: /createStatelessMcpHandler as createMcpHandler/.test(server),
  v2Factory: /type StatelessMcpServerInput = McpServerFactory;/.test(server) && /McpServerFactory[\s\S]*?\} from "@modelcontextprotocol\/server";/.test(server),
  factoryOverload: /declare function createMcpHandler\$1\(\s*factory: McpServerFactory,/.test(mcp),
  legacy: /declare function createLegacyMcpHandler\(/.test(mcp)
};
